import React from "react";
import HistoryTableRow from "./HistoryTableRowComponent";
import "./../css/profie.css";
import { Link } from "react-router-dom";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

const PERSIAN_DIGITS = [
  "۰",
  "۱",
  "۲",
  "۳",
  "۴",
  "۵",
  "۶",
  "۷",
  "۸",
  "۹",
];

const PERSIAN_MONTHS = [
  "",
  "فروردین",
  "اردیبهشت",
  "خرداد",
  "تیر",
  "مرداد",
  "شهریور",
  "مهر",
  "آبان",
  "آذر",
  "دی",
  "بهمن",
  "اسفند",
];

function toPersianDigits(value) {
  return String(value ?? "").replace(
    /\d/g,
    (d) => PERSIAN_DIGITS[Number(d)]
  );
}

function monthLabelFromDate(dateStr) {
  if (!dateStr) {
    return "";
  }

  const parts = String(dateStr).split("/");

  if (parts.length < 2) {
    return "";
  }

  const year = parts[0];
  const month = Number(parts[1]);

  const monthName = PERSIAN_MONTHS[month] || "";

  return `${monthName} ${toPersianDigits(year)}`;
}

class TechnicianProfilePage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      user: null,
      loading: true,
      authenticated: false,

      // فعلاً چون API پروفایل این اطلاعات را ندارد
      stats: null,
      history: [],
    };

    this.handleProfileClick = this.handleProfileClick.bind(this);
    this.handleChatClick = this.handleChatClick.bind(this);
    this.handleRowDetails = this.handleRowDetails.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getProfile();
      }
    );
  }

  getProfile = () => {
    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    if (!id) {
      console.error("PROFILE ID NOT FOUND");

      this.setState({
        loading: false,
      });

      return;
    }

    fetch(`${API_URL}/profile?id=${id}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP ERROR: ${response.status}`);
        }

        return response.json();
      })
      .then((data) => {
        console.log("PROFILE API:", data);

        if (String(data.status) !== "1" || !data.user) {
          console.error("PROFILE API ERROR:", data);

          this.setState({
            user: null,
            loading: false,
          });

          return;
        }

        this.setState({
          user: data.user,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET PROFILE ERROR:", error);

        this.setState({
          user: null,
          loading: false,
        });
      });
  };

  handleProfileClick() {
    console.log("رفتن به پروفایل");
  }

  handleChatClick() {
    console.log("رفتن به گفتگو");
  }

  handleRowDetails(id) {
    console.log("جزئیات سابقه:", id);
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      user,
      loading,
      stats,
      history,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت اطلاعات تعمیرکار...
        </div>
      );
    }

    if (!user) {
      return (
        <div className="text-center text-muted py-5">
          اطلاعات تعمیرکار پیدا نشد.
        </div>
      );
    }

    const fullName = `${user.name || ""} ${user.family || ""}`.trim();

    const avatar = user.image
      ? `https://iranaserviceapp.ir/test/${user.image}`
      : `https://ui-avatars.com/api/?name=${encodeURIComponent(
          fullName || "کاربر"
        )}&background=e9ecef&color=495057`;

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* کارت پروفایل */}
          <div className="d-flex align-items-center justify-content-between border rounded-4 p-3 mb-4">
            <div className="d-flex align-items-center gap-3 w-100">

              <img
                src={avatar}
                alt={fullName}
                width="56"
                height="56"
                className="rounded-circle"
                style={{
                  objectFit: "cover",
                }}
              />

              <div>
                <div className="fw-semibold text-dark">
                  {fullName || "بدون نام"}
                </div>

                <div className="text-muted small">
                  {user.mobile || "—"}
                </div>
              </div>

              {/* دکمه‌ها */}
              <div className="d-flex flex-column gap-2 me-auto">

                <button
                  type="button"
                  onClick={this.handleProfileClick}
                  className="btn btn-primary rounded-pill btn-sm px-4 py-2"
                >
                  پروفایل
                </button>

                <button
                  type="button"
                  onClick={this.handleChatClick}
                  className="btn btn-outline-primary rounded-pill btn-sm px-4 py-2"
                >
                  گفتگو
                </button>

              </div>
            </div>
          </div>

          {/* اطلاعات پایه تعمیرکار */}
          <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
            اطلاعات تعمیرکار
          </h2>

          <div className="border rounded-4 p-3 mb-4">

            <div className="d-flex align-items-center justify-content-between py-2 border-bottom">
              <span className="text-muted">
                نام و نام خانوادگی
              </span>

              <span className="fw-semibold">
                {fullName || "—"}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between py-2 border-bottom">
              <span className="text-muted">
                شماره موبایل
              </span>

              <span className="fw-semibold">
                {user.mobile || "—"}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between py-2 border-bottom">
              <span className="text-muted">
                استان
              </span>

              <span className="fw-semibold">
                {user.state_model?.name || "—"}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between py-2 border-bottom">
              <span className="text-muted">
                شهر
              </span>

              <span className="fw-semibold">
                {user.city_model?.name || "—"}
              </span>
            </div>

            <div className="d-flex align-items-center justify-content-between py-2">
              <span className="text-muted">
                آدرس
              </span>

              <span
                className="fw-semibold text-end"
                style={{ maxWidth: "65%" }}
              >
                {user.address || "—"}
              </span>
            </div>

          </div>

          {/* آمار */}
          {stats && (
            <>
              <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
                آمار
              </h2>

              <div className="border rounded-4 p-3 mb-4 d-flex flex-column gap-3">

                <div className="d-flex align-items-center justify-content-between">
                  <span className="text-muted">
                    تسویه شده
                  </span>

                  <span
                    className="fw-semibold"
                    style={{ color: "#5b9bf0" }}
                  >
                    {toPersianDigits(stats.settled)}
                  </span>
                </div>

                <div className="d-flex align-items-center justify-content-between">
                  <span className="text-muted">
                    کنسل شده توسط تعمیرکار
                  </span>

                  <span className="fw-semibold text-danger">
                    {toPersianDigits(stats.canceledByTechnician)}
                  </span>
                </div>

                <div className="d-flex align-items-center justify-content-between">
                  <span className="text-muted">
                    مجدد فعال‌سازی شده
                  </span>

                  <span className="fw-semibold text-dark">
                    {toPersianDigits(stats.reactivated)}
                  </span>
                </div>

              </div>
            </>
          )}

          {/* سوابق */}
          {history.length > 0 && (
            <>
              <h2 className="text-center fs-6 fw-semibold text-dark mb-3">
                سوابق
              </h2>

              <div className="border rounded-4 overflow-hidden">

                {/* سرستون */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "1fr 1.3fr 1fr 0.8fr",
                    alignItems: "center",
                  }}
                  className="py-3 border-bottom table-header"
                >
                  <span className="text-center small">
                    نوع دستگاه
                  </span>

                  <span className="text-center small">
                    ایراد دستگاه
                  </span>

                  <span className="text-center small">
                    زمان مراجعه
                  </span>

                  <span className="text-center small">
                    جزئیات
                  </span>
                </div>

                {history.map((record) => {
                  const monthLabel = monthLabelFromDate(record.date);

                  return (
                    <React.Fragment key={record.id}>

                      {monthLabel && (
                        <div className="text-center small text-muted py-2 bg-light border-bottom">
                          {monthLabel}
                        </div>
                      )}

                      <Link
                        to={`/request-details/${record.id}`}
                        className="text-decoration-none text-dark d-block"
                      >
                        <HistoryTableRow
                          record={record}
                          onDetails={this.handleRowDetails}
                        />
                      </Link>

                    </React.Fragment>
                  );
                })}

              </div>
            </>
          )}

        </div>
      </div>
    );
  }
}

export default withRouter(TechnicianProfilePage);
